'use client';
import { useEffect, useRef, useState, type CSSProperties, type RefObject } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion, useTween } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { mxT, Spin, Swap, Tip } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './context-meter.css';

/** One kind of thing in the context */
export interface ContextPart {
  key: string;
  /** Like "Files", "Tool output" or "Chat" */
  label: string;
  /** How many tokens it takes */
  tokens: number;
  /** Its colour in the bar and the legend. Defaults to the accent, violet, teal and a neutral grey, in order */
  color?: string;
  /** What is in it, shown when you hover its row, like "PricingCard.tsx 18.2k, tokens.css 6.1k" */
  items?: string;
}

export interface ContextMeterProps {
  parts: ContextPart[];
  /** The size of the context window, in tokens, like 200000 */
  limit: number;
  /** From this share of the limit (0 to 1) the ring turns orange. Defaults to 0.85 */
  warnAt?: number;
  /** A line under the legend, like "Freed 41.2k tokens. 9 decisions kept". Crossfades when it changes */
  message?: string;
  /** warn shows the message as a warning notice (a faint warning tint, the filled warning sign, the words in the text colour)
      and puts Compact in the warning tint, as the action that resolves it; ok shows it as a plain line with the green tick */
  messageTone?: 'warn' | 'ok';
  /** Called by Compact. Return a promise and, until it settles, the button gives way to a "Compacting…" status line with a spinner */
  onCompact?: () => void | Promise<void>;
  /** Set once the context is compacted: the button turns into Undo, which calls onUndo */
  compacted?: boolean;
  onUndo?: () => void;
  /** The quiet line beside the button. Defaults to what Compact does */
  hint?: string;
  /** The line beside the button while Compact runs, with a moving highlight. Defaults to "Summarising older turns" */
  busyHint?: string;
  /** Whether the panel is open. Leave it out to let the pill toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Which side of the pill the panel opens on. Defaults to top, above the pill, as it sits under a chat composer. When the
      window, or a box round the meter that clips it, has no room on that side and more on the other, it opens there instead */
  placement?: 'top' | 'bottom';
  className?: string;
}

/** The room the panel may open into: the window, cut by any box round the meter that clips what spills out of it */
function roomOf(el: HTMLElement) {
  let top = 0, bottom = innerHeight;
  for (let a = el.parentElement; a && a !== document.documentElement; a = a.parentElement) {
    if (getComputedStyle(a).overflowY === 'visible') continue;
    const r = a.getBoundingClientRect(); top = Math.max(top, r.top); bottom = Math.min(bottom, r.bottom);
  }
  return { top, bottom };
}


/** A button as wide as its words: when they change it eases to its new width on the motion pieces' spring, keeping no room
    for a longer word */
function useEaseWidth(ref: RefObject<HTMLElement | null>) {
  const reduce = useReducedMotion();
  useEffect(() => {
    const el = ref.current; if (!el || reduce || typeof ResizeObserver === 'undefined') return;
    let w = 0, busy: Animation | null = null;
    const ro = new ResizeObserver(() => {
      if (busy) return;
      const w1 = el.getBoundingClientRect().width;
      if (w && Math.abs(w1 - w) > .5) {
        busy = el.animate([{ width: w + 'px' }, { width: w1 + 'px' }], { duration: mxT(el, 't-in', 360), easing: mxT(el, 'ease-spring', 'ease') });
        busy.finished.catch(() => {}).then(() => { busy = null; w = el.getBoundingClientRect().width; });
      }
      w = w1;
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref, reduce]);
}

const PALETTE = ['var(--dm-c1)', 'var(--dm-c2)', 'var(--dm-c6)', 'var(--dm-muted)'];
const k = (n: number) => (n / 1000).toFixed(1) + 'k';

/** A number that counts to its new value (it starts on its first value) */
function Count({ value, ms = 900, format }: { value: number; ms?: number; format: (n: number) => string }) {
  return <>{format(useTween(value, ms))}</>;
}

/** How full the context is and what fills it: a pill with a ring that opens one bar split by kind, a legend whose rows list
 *  what is in them, and Compact. The panel opens above the pill (placement), and Escape closes it. */
export function ContextMeter({ parts, limit, warnAt = .85, message, messageTone = 'ok', onCompact, compacted = false, onUndo,
  hint = 'Summarises older turns', busyHint = 'Summarising older turns', open, defaultOpen = true, onOpenChange, placement = 'top', className }: ContextMeterProps) {
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const [busy, setBusy] = useState(false);
  const [lit, setLit] = useState<string | null>(null);
  // it opens on its real numbers; they only count when something changes
  const ready = true;
  const total = parts.reduce((t, p) => t + p.tokens, 0), share = ready ? total / limit : 0, pct = Math.round(share * 100);
  const root = useRef<HTMLDivElement>(null), tg = useRef<HTMLButtonElement>(null), go = useRef<HTMLButtonElement>(null), pop = useRef<HTMLDivElement>(null);
  const leg = useRef<HTMLDivElement>(null);
  useHoverGlide(leg, '.dm-ctm-l');
  // the ring's moments (designme.dev, 26 Nov): a step up (or the drop after compacting) sends a thin bright highlight once along
  // the filled arc and lifts the ring a touch; as the count passes warnAt, the warning mark wipes along the arc (and back once
  // it drops below), never blending the two colours, and the pill nudges once. No halo or glow. Reduced motion: none of it
  const reduce = useReducedMotion();
  const ring = useRef<SVGSVGElement>(null), warc = useRef<SVGCircleElement>(null), shine = useRef<SVGCircleElement>(null);
  const counted = useTween(total, 900), hot = Math.round(counted / limit * 100) >= Math.round(warnAt * 100);
  const last = useRef(total);
  useEffect(() => {
    const was = last.current; last.current = total;
    const sv = ring.current, sh = shine.current; if (reduce || !sv || !sh || typeof sh.animate !== 'function' || Math.abs(total - was) < 50) return;
    const seg = Math.min(9, pct); sh.style.strokeDasharray = seg + ' 200';
    sh.animate([{ strokeDashoffset: 0, opacity: 0 }, { opacity: .9, offset: .5 }, { strokeDashoffset: -(pct - seg), opacity: 0 }], { duration: 450, easing: 'cubic-bezier(.65,0,.35,1)' });
    sv.animate([{ scale: 1 }, { scale: 1.06, offset: .2 }, { scale: 1 }], { duration: 350, easing: 'cubic-bezier(.23,1,.32,1)' });
  }, [total]); // eslint-disable-line react-hooks/exhaustive-deps
  const wasHot = useRef(hot);
  useIsoLayoutEffect(() => {
    const w = warc.current, was = wasHot.current; wasHot.current = hot; if (!w) return;
    if (hot === was) { if (hot) w.style.strokeDasharray = pct + ' 100'; return; }
    const ease = 'cubic-bezier(.65,0,.35,1)', from = parseFloat(w.style.strokeDasharray) || 0;
    w.style.transition = 'none';
    if (hot) {
      w.style.opacity = '1'; w.style.strokeDasharray = pct + ' 100';
      if (!reduce && typeof w.animate === 'function') {
        w.animate([{ strokeDasharray: '0 100' }, { strokeDasharray: pct + ' 100' }], { duration: 200, easing: ease });
        tg.current?.animate([{ translate: '0 0' }, { translate: '3px 0', offset: .22 }, { translate: '-1.4px 0', offset: .6 }, { translate: '0 0' }], { duration: 380, easing: 'ease-out' });
      }
    } else {
      w.style.strokeDasharray = '0 100';
      if (reduce || typeof w.animate !== 'function') w.style.opacity = '0';
      else w.animate([{ strokeDasharray: from + ' 100' }, { strokeDasharray: '0 100' }], { duration: 200, easing: ease }).onfinish = () => { if (!wasHot.current) w.style.opacity = '0'; };
    }
    void w.getBoundingClientRect(); w.style.transition = '';
  }, [hot, pct]);
  useEaseWidth(go);
  // the side it opens on is chosen as it opens: the placement's side, or the other one when that side has no room for the
  // panel (its height, its padding while it is still easing in, and the gap) and the other has more
  const [side, setSide] = useState(placement);
  const full = useRef(0);
  useIsoLayoutEffect(() => {
    const el = pop.current, b = tg.current; if (!isOpen || !el || !b) return;
    full.current = Math.max(full.current, el.scrollHeight);
    const room = roomOf(b), r = b.getBoundingClientRect(), need = full.current + 44, above = r.top - room.top, below = room.bottom - r.bottom;
    const [want, other] = placement === 'top' ? [above, below] : [below, above];
    const up = placement === 'top' ? want >= need || want >= other : !(want >= need || want >= other);
    setSide(up ? 'top' : 'bottom');
  }, [isOpen, placement]);
  // Escape shuts the panel while the pointer or the focus is on the meter
  useEffect(() => {
    if (!isOpen) return;
    const key = (e: KeyboardEvent) => {
      const el = root.current; if (e.key !== 'Escape' || !el) return;
      const inside = el.contains(document.activeElement);
      if (inside || el.matches(':hover')) { setOpen(false); if (inside) tg.current?.focus({ preventScroll: true }); }
    };
    document.addEventListener('keydown', key);
    return () => document.removeEventListener('keydown', key);
  }, [isOpen]); // eslint-disable-line react-hooks/exhaustive-deps
  const compact = async () => {
    if (busy) return;
    if (compacted) { onUndo?.(); return; }
    setBusy(true);
    try { await onCompact?.(); } finally { setBusy(false); }
  };

  return (
    <div ref={root} data-dm="" className={cx('dm-ctm', hot && 'dm-hot', className)} data-open={isOpen ? '1' : '0'} data-pos={side === 'top' ? 'up' : 'down'}>
      <button ref={tg} type="button" className="dm-ctm-tg" aria-expanded={isOpen} aria-label={`Context, ${pct}% used`} onClick={() => setOpen(!isOpen)}>
        <span className="dm-ctm-ring" aria-hidden="true">
          <svg ref={ring} viewBox="0 0 20 20"><circle className="dm-tr" cx="10" cy="10" r="7.5" /><circle className="dm-fl" cx="10" cy="10" r="7.5" pathLength={100} style={{ strokeDasharray: `${pct} 100` }} />
            <circle ref={warc} className="dm-fw" cx="10" cy="10" r="7.5" pathLength={100} /><circle ref={shine} className="dm-hl" cx="10" cy="10" r="7.5" pathLength={100} /></svg>
        </span>
        <span><span className="dm-ctm-pc dm-num"><Count value={ready ? total : 0} format={n => Math.round(n / limit * 100) + '%'} /></span> of context used</span>
        <Icon name="chev-d" size="xs" />
      </button>
      <div ref={pop} className="dm-ctm-pop dm-panel" role="region" aria-label="What fills the context" inert={!isOpen}>
        <div className="dm-ctm-ph"><span>In context</span><span className="dm-num"><b className="dm-ctm-tot"><Count value={ready ? total : 0} format={k} /></b> of {Math.round(limit / 1000)}k tokens</span></div>
        <div className={cx('dm-ctm-bar', lit && 'dm-hl')} aria-hidden="true">
          {parts.map((p, i) => <i key={p.key} className={lit === p.key ? 'dm-on' : undefined} style={{ width: (ready ? p.tokens / limit * 100 : 0) + '%', '--dm-c': p.color ?? PALETTE[i % PALETTE.length] } as CSSProperties} />)}
        </div>
        {/* one highlight glides from part to part (motion pieces) */}
        <div ref={leg} className="dm-ctm-leg dm-mx-glide" onPointerLeave={() => setLit(null)}>
          {parts.map((p, i) => {
            const row = (
              <div key={p.key} className="dm-ctm-l" style={{ '--dm-c': p.color ?? PALETTE[i % PALETTE.length] } as CSSProperties}
                onPointerEnter={() => setLit(p.key)} onFocus={() => setLit(p.key)} onBlur={() => setLit(null)} tabIndex={p.items ? 0 : undefined}>
                <span className="dm-sw" />{p.label}<span className="dm-v dm-num"><Count value={ready ? p.tokens : 0} format={k} /></span>
              </div>
            );
            return p.items ? <Tip key={p.key} label={p.items}>{row}</Tip> : row;
          })}
        </div>
        <div className={cx('dm-ctm-msg', message && 'dm-on', message && 'dm-' + messageTone)} aria-live="polite">
          <span>{message && <>{messageTone === 'warn'
            ? <svg className="dm-ctm-wi" viewBox="0 0 24 24" aria-hidden="true"><path className="dm-a" d="M12 3.6 2.6 19.9h18.8z" /><path className="dm-b" d="M12 9.6v4.4M12 17v.01" /></svg>
            : <Icon name="ok" size="xs" />}<Swap>{message}</Swap></>}</span>
        </div>
        {(onCompact || onUndo) && (
          <div className="dm-ctm-f">
            {busy ? <span className="dm-ctm-hint"><span className="dm-shim">{busyHint}</span></span> : <Swap className="dm-ctm-hint">{hint}</Swap>}
            {/* while it compacts nothing can be pressed, so it says so where the button was, in the loader's sweep, and the button
                comes back as Undo once it is done */}
            {busy
              ? <span className="dm-ctm-run" role="status"><Spin /><span className="dm-shim">Compacting…</span></span>
              : <button ref={go} type="button" className={cx('dm-pill dm-sm dm-ctm-go dm-mx-press', message && messageTone === 'warn' ? 'dm-warn' : 'dm-line')} onClick={compact}>{compacted ? 'Undo' : 'Compact'}</button>}
          </div>
        )}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Context meter ---------- */
/* a pill with the ring opens what fills the context: one bar split by kind, a legend whose rows list their items, and Compact */
/* it never anchors the page's scroll, so the page can't follow it as it changes; on a card it sits in the middle of its room */
/* the panel opens above the pill, as it does under a chat composer (owner, 26 Nov), and below it only where there is no room
   above (data-pos="down", set as it opens). The pill comes first for the keyboard and the panel is drawn above it. On a card
   the two sit centred together: the pill rests in the middle and glides down as the panel opens over it */
.dm-ctm{display:flex;flex-direction:column-reverse;align-items:flex-start;justify-content:center;gap:var(--dm-s-2);width:100%;max-width:340px;margin-inline:auto;overflow-anchor:none}
.dm-stage-in:has(>.dm-ctm){overflow-anchor:none}
.dm-stage-in>.dm-ctm{min-height:inherit}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-ctm :is(.dm-pill,.dm-ib,.dm-ctm-tg):active{transform:none}
.dm-ctm[data-pos="down"]{flex-direction:column}
.dm-ctm-tg{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:32px;padding:0 10px 0 7px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:var(--dm-shadow);transition:box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-ctm-tg:hover{box-shadow:var(--dm-shadow-pop)}}
.dm-ctm-tg .dm-ctm-pc{color:var(--dm-fg);font-weight:500}
.dm-ctm-tg>svg:last-child{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
/* the chevron points the way the panel opens while it is shut, and turns over once it is open: up, then down (as Run drawer's
   does); below, it is the usual down, then up */
.dm-ctm[data-open="0"]:not([data-pos="down"]) .dm-ctm-tg>svg:last-child,.dm-ctm[data-pos="down"][data-open="1"] .dm-ctm-tg>svg:last-child{transform:rotate(180deg)}
/* shut, the panel folds away to nothing (owner, 17 Nov: no room kept for a later state): its height eases to 0 as it fades,
   so the meter shrinks with it and stays centred in its stage, and opens back the same way. Where the browser can't ease a
   height to auto, it opens and shuts at once. It only fades as its height eases, with no glide on top (owner, 19 Nov). Its
   content sits 16px in from every edge (owner, 18 Nov). It grows out of the pill: its edge next to the pill stays put, its
   content holds to that edge as the far one eases out, and it scales a little from the pill's corner as it fades */
.dm-ctm{interpolate-size:allow-keywords}
.dm-ctm-pop{width:100%;min-height:0;padding:var(--dm-s-4);display:flex;flex-direction:column;justify-content:flex-end;gap:var(--dm-s-3);overflow:clip;transform-origin:0 100%;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease),height .42s var(--dm-ease),margin .42s var(--dm-ease),padding .42s var(--dm-ease),visibility 0s}
.dm-ctm[data-pos="down"] .dm-ctm-pop{justify-content:flex-start;transform-origin:0 0}
.dm-ctm[data-open="0"] .dm-ctm-pop{height:0;margin-bottom:calc(-1 * var(--dm-s-2));padding-block:0;opacity:0;transform:scale(.98);visibility:hidden;pointer-events:none;transition:opacity .16s var(--dm-ease),transform .32s var(--dm-ease),height .32s var(--dm-ease),margin .32s var(--dm-ease),padding .32s var(--dm-ease),visibility 0s .32s}
.dm-ctm[data-pos="down"][data-open="0"] .dm-ctm-pop{margin-bottom:0;margin-top:calc(-1 * var(--dm-s-2))}
@media (prefers-reduced-motion:reduce){.dm-ctm-pop,.dm-ctm[data-open="0"] .dm-ctm-pop{transition:none}}
.dm-ctm-ph{display:flex;align-items:baseline;justify-content:space-between;gap:var(--dm-s-3);font-size:13px;line-height:18px;color:var(--dm-muted)}
.dm-ctm-ph b{color:var(--dm-fg);font-weight:500}
/* the bar: one part per kind in the chart palette (the accent first, a neutral grey for the quiet part), on the neutral rail */
.dm-ctm-bar{display:flex;gap:2px;height:8px;border-radius:var(--dm-r-xs);background:var(--dm-rail);overflow:hidden}
.dm-ctm-bar i{height:100%;width:0;flex:none;background:var(--dm-c);transition:width .42s var(--dm-ease),opacity .16s}
.dm-ctm-bar.dm-hl i:not(.dm-on){opacity:.25}
/* the legend's rows answer the pointer: the swatch sits on the content's edge and the hover reaches out round it */
/* (the swatches start and the values end on the content's 16px column, as the head's words do; a row's hover fill reaches
   8px out round it, into the padding (owner, 26 Nov)) */
.dm-ctm-leg{display:flex;flex-direction:column;margin:0 calc(-1 * var(--dm-s-2))}
.dm-ctm-l{display:flex;align-items:center;gap:var(--dm-s-2);padding:5px var(--dm-s-2);border-radius:var(--dm-r-sm);font-size:13px;line-height:18px;color:var(--dm-fg2);cursor:default;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-ctm-l:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
/* its motion (the core's motion pieces, owner, 26 Nov): one highlight glides from part to part in the legend, in the hover's
   own grey (.mx-glide); a press on Compact shows at once; its box eases to its new words' width on the spring (mxWidth()) */
.dm-ctm-leg{--dm-hg-bg:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
:root[data-style="clean"] .dm-ctm-leg,:root [data-style="clean"] .dm-ctm-leg,:root [data-style="clean"].dm-ctm-leg{--dm-hg-bg:var(--dm-row)}
/* the swatch is centred in a 16px column, the column of the message's sign and tick below, so their words line up */
.dm-ctm-l .dm-sw{width:8px;height:8px;margin:0 4px 0 0;border-radius:var(--dm-r-tiny,2px);flex:none;background:var(--dm-c)}
.dm-ctm-l .dm-v{margin-left:auto;color:var(--dm-fg)}
/* the message takes no room until it has something to say (owner, 17 Nov), and opens smoothly when it does. A warning is a
   warning notice (owner, 18 Nov): a faint warning tint, the filled warning sign in the warning mark and the words in the text
   colour; the action that resolves it is Compact, below, in the warning tint while it shows. A result is a plain line with
   the green tick */
.dm-ctm-msg{display:grid;grid-template-rows:0fr;margin-top:calc(-1 * var(--dm-s-3));font-size:13px;line-height:18px;color:var(--dm-fg);opacity:0;transition:grid-template-rows .32s var(--dm-ease),margin .32s var(--dm-ease),opacity .24s var(--dm-ease)}
.dm-ctm-msg.dm-on{grid-template-rows:1fr;margin-top:0;opacity:1}
.dm-ctm-msg>span{display:flex;align-items:flex-start;gap:var(--dm-s-2);min-height:0;overflow:hidden}
/* (the warning's tint and padding ease away as it turns into the result, so the panel eases to its new height in one motion) */
.dm-ctm-msg>span{transition:padding .32s var(--dm-ease),background-color .32s var(--dm-ease)}
.dm-ctm-msg>span>svg,.dm-ctm-msg>span>svg.dm-i{flex:none;width:16px;height:16px;margin-top:1px}
/* the notice reaches out as far as the legend's hover, with the legend's padding, so its sign sits in the swatches' column
   and its words on the legend's words */
/* (a message's mark sits on the legend's swatch column and its words on the legend's words; the warning's tint is as wide
   as the content, its words 6px inside it) */
.dm-ctm-msg:not(.dm-warn)>span{padding-inline:6px}
.dm-ctm-msg.dm-warn>span{margin:0;padding:8px 6px;border-radius:var(--dm-r-sm);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)}
.dm-ctm-wi{overflow:visible}
.dm-ctm-wi .dm-a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.dm-ctm-wi .dm-b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.dm-ctm-msg.dm-ok>span>svg{color:var(--dm-ok-mark)}
@media (prefers-reduced-motion:reduce){.dm-ctm-msg{transition:none}}
.dm-ctm-f{display:flex;align-items:center;gap:10px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ctm-go{overflow:hidden;white-space:nowrap;justify-content:flex-start}
/* while it compacts nothing can be pressed, so it says so where the button was (owner, 21 Nov: "should this be gray button?
   especially the loading animation?"): the spinner in the accent and the words in the loader's sweep, as plain words, the row
   keeping its height and its right edge; Undo comes in once it is done */
.dm-ctm-run{display:inline-flex;align-items:center;gap:6px;height:28px;flex:none;font-size:13px;color:var(--dm-fg);white-space:nowrap}
.dm-ctm-run[hidden]{display:none}
.dm-ctm-run .dm-spin{width:12px;height:12px;color:var(--dm-accent-mark,var(--dm-accent))}
.dm-ctm-f .dm-ctm-hint{flex:1;min-width:0;font-size:13px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the ring: inside the meter's pill, and as its own button where Agent harness puts it in the composer. Its track is the
   neutral rail and its fill the accent's mark colour (3:1), the warning mark near the limit */
.dm-ctm-ft{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;color:var(--dm-fg2)}
.dm-ctm-ring{width:30px;height:30px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-ctm-ring:hover{background:var(--dm-row)}}
.dm-ctm-tg .dm-ctm-ring{width:20px;height:20px;background:none}
.dm-ctm-ring svg{width:18px;height:18px;transform:rotate(-90deg);overflow:visible}
.dm-ctm-ring circle{fill:none;stroke-width:2.6}
.dm-ctm-ring .dm-tr{stroke:var(--dm-rail)}
